					return false;
				}
				if (!player.canUse({ name: event.card.name }, targets[i], false, false)) {
					return false;
				}
			}
			if (player.hasCard("shenmiguo")) {
				return true;
			}
			if (player.hasCard("yuchankan")) {
				return true;
