								if(get.tag(card,'respondSha')||get.tag(card,'respondShan')){
									if(get.attitude(player,target)>0&&card.name=='juedou') return;
									return [0.5,target.countCards('h','sha')+target.countCards('h','shan')];
								}
							}
						}
					},
